def eval_expression(expr: str) -> int:
    """
    与式 `expr` を計算し、結果を整数として返す。

    演算子の優先順位:
    - 括弧内が最優先
    - 乗除（*, /）
    - 加減（+, -）

    負の数もサポートする。
    ゼロで割る場合は ZeroDivisionError を発生させる。
    """
    # トークナイズ
    def tokenize(expression: str):
        tokens = []
        i = 0
        while i < len(expression):
            if expression[i] == ' ':
                i += 1
            elif expression[i] == '(':
                tokens.append('(')
                i += 1
            elif expression[i] == ')':
                tokens.append(')')
                i += 1
            elif expression[i] in '+-*/':
                tokens.append(expression[i])
                i += 1
            elif expression[i].isdigit():
                start = i
                while i < len(expression) and expression[i].isdigit():
                    i += 1
                tokens.append(int(expression[start:i]))
            else:
                raise SyntaxError(f"無効な文字: '{expression[i]}'")
        return tokens

    # シャunting-yardアルゴリズムまたは再帰下降パーサーを使用
    # ここでは再帰下降パーサーを実装する

    class Parser:
        def __init__(self, tokens):
            self.tokens = tokens
            self.pos = 0

        def peek(self):
            if self.pos < len(self.tokens):
                return self.tokens[self.pos]
            return None

        def consume(self):
            token = self.tokens[self.pos]
            self.pos += 1
            return token

        def parse(self) -> int:
            result = self.parse_expression()
            if self.pos != len(self.tokens):
                raise SyntaxError("unexpected token")
            return result

        def parse_expression(self) -> int:
            """解析: expression := term (('+' | '-') term)*"""
            result = self.parse_term()
            while self.peek() in ('+', '-'):
                op = self.consume()
                right = self.parse_term()
                if op == '+':
                    result += right
                else:
                    result -= right
            return result

        def parse_term(self) -> int:
            """解析: term := factor (('*' | '/') factor)*"""
            result = self.parse_factor()
            while self.peek() in ('*', '/'):
                op = self.consume()
                right = self.parse_factor()
                if op == '*':
                    result *= right
                else:
                    if right == 0:
                        raise ZeroDivisionError("ゼロで割ることができません")
                    result = result // right if (result >= 0) == (right >= 0) else -((-result) // right)
            return result

        def parse_factor(self) -> int:
            """解析: factor := ['+' | '-'] (number | '(' expression ')')
            単項の+,-をサポートする。"""
            # 単項演算子の処理
            if self.peek() == '+':
                self.consume()
                return self.parse_factor()
            elif self.peek() == '-':
                self.consume()
                return -self.parse_factor()

            if self.peek() == '(':
                self.consume()  # '('
                result = self.parse_expression()
                if self.peek() != ')':
                    raise SyntaxError("閉じ括弧がありません")
                self.consume()  # ')'
                return result
            elif isinstance(self.peek(), int):
                num = self.consume()
                return num
            else:
                raise SyntaxError(f"予期しないトークン: {self.peek()}")

    tokens = tokenize(expr)
    if not tokens:
        raise SyntaxError("空の式")

    parser = Parser(tokens)
    return parser.parse()
